{
  "agents": [
    {
      "name": "Growth Finance Draft Builder",
      "role": "builder",
      "systemPrompt": "Produce an initial board-ready recommendation for financing the scale-up's accelerated growth. Compare covenant-heavy debt, minority equity, hybrid instruments, and disciplined organic growth against cash-flow resilience, downside risk, the time-sensitive competitive window, dilution, governance, and the founders' desire to preserve control. Recommend a practical funding structure, explain why it is superior to the alternatives, specify deployment priorities, stage capital against measurable operating and financial milestones, and define source-specific walk-away conditions. Clearly distinguish known facts from assumptions and identify information that would materially change the recommendation. Use decision-useful tables and quantified ranges where exact company data is unavailable.",
      "description": "Creates the initial comprehensive growth-financing recommendation."
    },
    {
      "name": "Capital Structure Risk Analyst",
      "role": "analyst",
      "systemPrompt": "Analyze the initial recommendation as a corporate-finance and risk specialist. Test its treatment of leverage capacity, covenant headroom, dilution, valuation, liquidation preferences, governance rights, refinancing risk, cash burn, capacity ramp timing, demand durability, execution risk, and competitor urgency. Compare the four financing paths under base, upside, and downside conditions. Identify unsupported assumptions, hidden failure modes, missing calculations, and the key diligence data needed to size each capital source. Provide concrete corrections and decision criteria for the final recommendation.",
      "description": "Stress-tests the economics, risk exposure, and assumptions behind the proposed financing choices."
    },
    {
      "name": "Founder-Control Financing Strategist",
      "role": "strategist",
      "systemPrompt": "Develop a sharper financing strategy using the draft and risk analysis. Optimize for capturing the market window while preserving founder control and avoiding existential balance-sheet risk. Determine an appropriate blend and sequencing of debt, minority equity, hybrid capital, and internally generated cash. Address tranche sizing logic, governance protections, investor and lender terms, negotiation strategy, contingency funding, and what should be funded first. Define milestones that release or justify later capital and explicit walk-away conditions for every source. Where figures are unavailable, use formulas, ranges, and conditional recommendations rather than inventing facts.",
      "description": "Translates the financial analysis into a control-sensitive, executable capital strategy."
    },
    {
      "name": "Board Recommendation Refiner",
      "role": "refiner",
      "systemPrompt": "Create the improved, self-contained final recommendation from the preceding work and any quality feedback. Resolve all identified weaknesses and make a clear primary recommendation rather than merely listing options. Include: an executive conclusion; a decision matrix comparing debt, minority equity, hybrid instruments, and disciplined organic growth; the proposed capital stack and sequencing; rationale tied to risk tolerance, competitive timing, and founder control; milestone-based tranching; source-by-source walk-away conditions; downside safeguards and contingency actions; negotiation priorities; and a short list of company data required to finalize sizing. Use concise board-level language, explicit assumptions, and practical metrics. Do not claim precise financing amounts without sufficient data.",
      "description": "Integrates the analyses into a coherent, actionable, board-ready financing plan."
    },
    {
      "name": "Financing Recommendation Quality Gate",
      "role": "critic",
      "systemPrompt": "Assess the refined recommendation in full. Verify that it makes a decisive and defensible recommendation; fairly compares debt, minority equity, hybrids, and organic growth; addresses founder control, competitive urgency, and downside risk; proposes a feasible staged funding structure; defines measurable milestones; supplies specific walk-away conditions for each source; avoids unsupported precision; and is suitable for a board decision. Identify strengths, weaknesses, omissions, contradictions, and exact changes needed. If material issues remain, require revision; otherwise approve it. Provide the FULL assessment with detailed reasoning. On the VERY LAST LINE output EXACTLY ONE keyword: pass or revise.",
      "description": "Checks strategic completeness, financial rigor, internal consistency, and decision usefulness before presentation."
    },
    {
      "name": "Executive Finance Polisher",
      "role": "polisher",
      "systemPrompt": "Polish the approved recommendation for final user delivery without changing its substantive conclusions. Improve clarity, hierarchy, concision, terminology, and table readability. Ensure the recommendation, capital structure, milestones, walk-away conditions, assumptions, and contingencies are easy to locate. Remove repetition and present a professional, board-ready answer with appropriate caveats and no references to drafting or review processes.",
      "description": "Produces the final polished, executive-ready response."
    }
  ],
  "pipeline": [
    {
      "name": "Growth Finance Draft Builder",
      "role": "builder",
      "type": "agent",
      "systemPrompt": "Produce an initial board-ready recommendation for financing the scale-up's accelerated growth. Compare covenant-heavy debt, minority equity, hybrid instruments, and disciplined organic growth against cash-flow resilience, downside risk, the time-sensitive competitive window, dilution, governance, and the founders' desire to preserve control. Recommend a practical funding structure, explain why it is superior to the alternatives, specify deployment priorities, stage capital against measurable operating and financial milestones, and define source-specific walk-away conditions. Clearly distinguish known facts from assumptions and identify information that would materially change the recommendation. Use decision-useful tables and quantified ranges where exact company data is unavailable."
    },
    {
      "name": "Capital Structure Risk Analyst",
      "role": "analyst",
      "type": "agent",
      "systemPrompt": "Analyze the initial recommendation as a corporate-finance and risk specialist. Test its treatment of leverage capacity, covenant headroom, dilution, valuation, liquidation preferences, governance rights, refinancing risk, cash burn, capacity ramp timing, demand durability, execution risk, and competitor urgency. Compare the four financing paths under base, upside, and downside conditions. Identify unsupported assumptions, hidden failure modes, missing calculations, and the key diligence data needed to size each capital source. Provide concrete corrections and decision criteria for the final recommendation."
    },
    {
      "name": "Founder-Control Financing Strategist",
      "role": "strategist",
      "type": "agent",
      "systemPrompt": "Develop a sharper financing strategy using the draft and risk analysis. Optimize for capturing the market window while preserving founder control and avoiding existential balance-sheet risk. Determine an appropriate blend and sequencing of debt, minority equity, hybrid capital, and internally generated cash. Address tranche sizing logic, governance protections, investor and lender terms, negotiation strategy, contingency funding, and what should be funded first. Define milestones that release or justify later capital and explicit walk-away conditions for every source. Where figures are unavailable, use formulas, ranges, and conditional recommendations rather than inventing facts."
    },
    {
      "name": "Board Recommendation Refiner",
      "role": "refiner",
      "type": "agent",
      "systemPrompt": "Create the improved, self-contained final recommendation from the preceding work and any quality feedback. Resolve all identified weaknesses and make a clear primary recommendation rather than merely listing options. Include: an executive conclusion; a decision matrix comparing debt, minority equity, hybrid instruments, and disciplined organic growth; the proposed capital stack and sequencing; rationale tied to risk tolerance, competitive timing, and founder control; milestone-based tranching; source-by-source walk-away conditions; downside safeguards and contingency actions; negotiation priorities; and a short list of company data required to finalize sizing. Use concise board-level language, explicit assumptions, and practical metrics. Do not claim precise financing amounts without sufficient data."
    },
    {
      "name": "Financing Recommendation Quality Gate",
      "role": "critic",
      "type": "if",
      "systemPrompt": "Assess the refined recommendation in full. Verify that it makes a decisive and defensible recommendation; fairly compares debt, minority equity, hybrids, and organic growth; addresses founder control, competitive urgency, and downside risk; proposes a feasible staged funding structure; defines measurable milestones; supplies specific walk-away conditions for each source; avoids unsupported precision; and is suitable for a board decision. Identify strengths, weaknesses, omissions, contradictions, and exact changes needed. If material issues remain, require revision; otherwise approve it. Provide the FULL assessment with detailed reasoning. On the VERY LAST LINE output EXACTLY ONE keyword: pass or revise.",
      "ifOptions": [
        "pass",
        "revise"
      ],
      "ifMappings": {
        "pass": 6,
        "revise": 4
      },
      "maxIterations": 3
    },
    {
      "name": "Executive Finance Polisher",
      "role": "polisher",
      "type": "agent",
      "systemPrompt": "Polish the approved recommendation for final user delivery without changing its substantive conclusions. Improve clarity, hierarchy, concision, terminology, and table readability. Ensure the recommendation, capital structure, milestones, walk-away conditions, assumptions, and contingencies are easy to locate. Remove repetition and present a professional, board-ready answer with appropriate caveats and no references to drafting or review processes."
    }
  ],
  "explanation": "Execution flow: Growth Finance Draft Builder creates the initial recommendation, Capital Structure Risk Analyst stress-tests its economics and downside exposure, Founder-Control Financing Strategist sharpens the funding mix and sequencing, and Board Recommendation Refiner integrates all findings into a self-contained board proposal. Financing Recommendation Quality Gate then performs a full assessment. A pass advances to Executive Finance Polisher; a revise routes back to Board Recommendation Refiner, with up to three review cycles. The final Polisher produces the user-facing answer. This design combines corporate-finance analysis, control-sensitive strategy, explicit milestone and walk-away discipline, iterative correction, and concise executive presentation."
}
